CREATE TABLE public.reports (
  id text PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  lat double precision NOT NULL,
  lng double precision NOT NULL,
  area text NOT NULL DEFAULT '',
  description text NOT NULL DEFAULT '',
  category text,
  exposure text NOT NULL DEFAULT 'unknown',
  status text NOT NULL DEFAULT 'SUBMITTED',
  incident_id text,
  consent boolean NOT NULL DEFAULT false,
  image text NOT NULL,
  output jsonb NOT NULL,
  history jsonb NOT NULL DEFAULT '[]'::jsonb,
  verification jsonb,
  work_order jsonb,
  prior_visible_area double precision,
  rejected_links jsonb NOT NULL DEFAULT '[]'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.reports TO anon, authenticated;
GRANT ALL ON public.reports TO service_role;
ALTER TABLE public.reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Demo: anyone can read reports" ON public.reports FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Demo: anyone can submit consented reports" ON public.reports FOR INSERT TO anon, authenticated WITH CHECK (consent = true);
CREATE POLICY "Demo: anyone can update reports" ON public.reports FOR UPDATE TO anon, authenticated USING (true) WITH CHECK (consent = true);
CREATE POLICY "Demo: anyone can remove reports on reset" ON public.reports FOR DELETE TO anon, authenticated USING (true);

CREATE OR REPLACE FUNCTION public.update_updated_at_column() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
CREATE TRIGGER reports_updated_at BEFORE UPDATE ON public.reports FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

ALTER TABLE public.reports REPLICA IDENTITY FULL;
ALTER PUBLICATION supabase_realtime ADD TABLE public.reports;

